documents.implicit:
yamaa: "1.0"
type: spec
domain: ADVS
keys: [STUDYID, USUBJID, VSDY]
input:
  VS: {path: vs.csv, types: {VSDTC: date, VSDY: int, SYSBP: float, DIABP: float}}
  HOME: {path: home.csv, types: {VSDTC: date, VSDY: int, SYSBP: float, DIABP: float}}
  PLAN: {path: plan.csv, key: [USUBJID], types: {DOSENUM: int, PLANDOSE: float}}
  DM: {path: dm.csv, types: {RFSTDTC: date, AGE: int}}
base: VS
output: {path: out.csv, columns: [STUDYID, USUBJID, VSDY, X, C, N]}
columns:
  - {name: STUDYID, type: str, derivation: VS.STUDYID}
  - {name: USUBJID, type: str, derivation: VS.USUBJID}
  - {name: VSDY, type: int, derivation: VS.VSDY}
  - {name: X, type: float, derivation: 0.0}
  - {name: C, type: str, derivation: "'A'"}
  - {name: N, type: int, derivation: 0}

