documents.whole:
yamaa: "1.0"
type: spec
domain: ADVS
keys: [STUDYID, USUBJID, PARAMCD]
input:
  VS: {path: vs.csv, types: {VSDTC: date, VSDY: int, SYSBP: float, DIABP: float}}
  HOME: {path: home.csv, key: [USUBJID], types: {VSDTC: date, VSDY: int, SYSBP: float, DIABP: float}}
  PLAN: {path: plan.csv, key: [USUBJID], types: {DOSENUM: int, PLANDOSE: float}}
  DM: {path: dm.csv, types: {RFSTDTC: date, AGE: int}}
output: {path: out.csv, columns: [STUDYID, USUBJID, PARAMCD, X, C]}
columns:
  - {name: STUDYID, type: str}
  - {name: USUBJID, type: str}
  - {name: PARAMCD, type: str}
  - {name: X, type: float, derivation: {case: [{when: "PARAMCD = 'CLINIC'", then: VS.SYSBP}, {otherwise: {aggregate: "MAX(HOME.SYSBP)"}}]}}
  - {name: C, type: str, derivation: "'A'"}
rows:
  - id: clinic
    dataset: VS
    derivations:
      STUDYID: VS.STUDYID
      USUBJID: VS.USUBJID
      PARAMCD: "'CLINIC'"
  - id: home
    dataset: HOME
    derivations:
      STUDYID: HOME.STUDYID
      USUBJID: HOME.USUBJID
      PARAMCD: "'HOME'"

