documents.subject:
yamaa: "1.0"
type: spec
domain: ADVS
keys: [STUDYID, USUBJID, PARAMCD]
input:
  VS: {path: vs.csv, types: {VSDTC: date, VSDY: int, SYSBP: float, DIABP: float}}
  HOME: {path: home.csv, types: {VSDTC: date, VSDY: int, SYSBP: float, DIABP: float}}
  PLAN: {path: plan.csv, key: [USUBJID], types: {DOSENUM: int, PLANDOSE: float}}
  DM: {path: dm.csv, types: {RFSTDTC: date, AGE: int}}
output: {path: out.csv, columns: [STUDYID, USUBJID, PARAMCD, AVAL, X, C]}
columns:
  - {name: STUDYID, type: str}
  - {name: USUBJID, type: str}
  - {name: PARAMCD, type: str}
  - {name: AVAL, type: float}
  - {name: X, type: float, derivation: 0.0}
  - {name: C, type: str, derivation: {mapping: {source: VS.VSTESTCD, dict: {"1": one}}}}
rows:
  - id: subject
    dataset: VS
    group_by: [VS.STUDYID, VS.USUBJID]
    derivations:
      STUDYID: VS.STUDYID
      USUBJID: VS.USUBJID
      PARAMCD: "'MAXBP'"
      AVAL: {aggregate: "MAX(VS.SYSBP)"}
      X: VS.SYSBP

documents.lookup:
yamaa: "1.0"
type: spec
domain: ADVS
keys: [STUDYID, USUBJID, VSDY]
input:
  VS: {path: vs.csv, types: {VSDTC: date, VSDY: int, SYSBP: float}}
