  - {name: USUBJID, type: str, derivation: VS.USUBJID}
  - {name: VSDY, type: int, derivation: VS.VSDY}
  - {name: X, type: float, derivation: P.D}
  - {name: C, type: str, derivation: "'A'"}
  - {name: N, type: int, derivation: 0}

documents.driven:
yamaa: "1.0"
type: spec
domain: ADVS
keys: [STUDYID, USUBJID, PARAMCD]
input:
  VS: {path: vs.csv, types: {VSDY: int, SYSBP: float}}
  PLAN: {path: plan.csv, key: [USUBJID], types: {DOSENUM: int, PLANDOSE: float, FIRST: int}}
intermediates:
  - {id: DOSES, dataset: PLAN, filter: "PLAN.DOSENUM > 0"}
output: {path: out.csv, columns: [STUDYID, USUBJID, PARAMCD, AVAL, X]}
columns:
  - {name: STUDYID, type: str}
  - {name: USUBJID, type: str}
  - {name: PARAMCD, type: str}
  - {name: AVAL, type: float}
  - {name: X, type: float, derivation: P.D}
rows:
  - id: vs
    dataset: VS
    derivations: {STUDYID: VS.STUDYID, USUBJID: VS.USUBJID, PARAMCD: "'V'", AVAL: VS.SYSBP}
  - id: dose
    dataset: DOSES
    derivations: {STUDYID: DOSES.STUDYID, USUBJID: DOSES.USUBJID, PARAMCD: "'D'", AVAL: DOSES.PLANDOSE}

edits.to:
- {name: VSTESTCD, type: int, derivation: VS.VSDY}
  - {name: X, type: float, derivation: DM.AGE}
  - {name: C, type: str, derivation: {flag: "DM.AGE > 1"}}

- {id: DOSES, dataset: PLAN, filter: "PLAN.DOSENUM > 0"}
  - {id: S, dataset: SELF, key: [USUBJID]}
  - {id: P, dataset: PLAN, key: [USUBJID], derivations: {D: S.AVAL}}
